"""Covenant registration and active CP151 clones, using the audited inventory."""
import os
from pathlib import Path
from baseline import ROOT
from target_schema import schema_database
from generate_hollow_choir import clone as _clone, companions as _companions, literal

SQL = Path(os.environ.get('CWC3_SQL_ROOT', ROOT))/'TheCandlekeepersCovenant/SQL'
CIV = 'CIVILIZATION_CWC3_COVENANT'
LEADER = 'LEADER_CWC3_COVENANT_SERAPHINE'
TRAIT = 'TRAIT_CWC3_COVENANT_NAMES_WE_CARRY'
UNIT = 'UNIT_CWC3_COVENANT_VIGIL_KEEPER'
HALL = 'BUILDING_CWC3_COVENANT_HALL'
PROMO = 'PROMOTION_CWC3_COVENANT_ETERNAL_VIGIL'
DEFENSE = 'PROMOTION_CWC3_COVENANT_DEFENSE'
PREFIX = 'TXT_KEY_CWC3_COVENANT_'
DUMMIES = [(f'CAPITAL_CULTURE_{i}', 'CULTURE') for i in range(1,13)] + [(f'CAPITAL_SCIENCE_{i}', 'SCIENCE') for i in range(1,5)] + [(f'HALL_SCIENCE_{i}', 'SCIENCE') for i in range(1,3)]

def clone(*args): return _clone(*args).replace('CWC3_ChoirClone', 'CWC3_CovenantClone')
def companions(*args): return _companions(*args).replace('CWC3_ChoirCompanion', 'CWC3_CovenantCompanion')
def write(kind, text):
    SQL.mkdir(parents=True, exist_ok=True)
    (SQL/f'Covenant_{kind}.sql').write_text('-- Generated by tools/generate_covenant.py.\n'+text, encoding='utf-8', newline='\n')

def main():
    db = schema_database()
    civ = """-- Verified pre-strength combat callback; no VP/balance options.
UPDATE CustomModOptions SET Value=1 WHERE Name='EVENTS_BATTLES';
INSERT INTO Colors(Type,Red,Green,Blue,Alpha) VALUES
 ('COLOR_CWC3_COVENANT_NAVY',0.035,0.07,0.16,1),('COLOR_CWC3_COVENANT_GOLD',0.93,0.70,0.28,1);
INSERT INTO PlayerColors(Type,PrimaryColor,SecondaryColor,TextColor) VALUES
 ('PLAYERCOLOR_CWC3_COVENANT','COLOR_CWC3_COVENANT_NAVY','COLOR_CWC3_COVENANT_GOLD','COLOR_PLAYER_WHITE_TEXT');
"""
    civ += f"INSERT INTO Traits(Type,Description,ShortDescription) VALUES ('{TRAIT}','{PREFIX}TRAIT_HELP','{PREFIX}TRAIT');\n"
    civ += clone('Civilizations','CIVILIZATION_AMERICA',CIV,dict(
        Description=PREFIX+'CIV',ShortDescription=PREFIX+'SHORT',Adjective=PREFIX+'ADJECTIVE',
        Civilopedia=PREFIX+'CIV_PEDIA',CivilopediaTag=PREFIX+'CIV5',Strategy=PREFIX+'STRATEGY',
        DefaultPlayerColor='PLAYERCOLOR_CWC3_COVENANT',Playable=1,AIPlayable=0,PackageID=None,
        IconAtlas='CWC3_COVENANT_CIV_ATLAS',AlphaIconAtlas='CWC3_COVENANT_ALPHA_ATLAS',PortraitIndex=0,
        DawnOfManQuote=PREFIX+'DAWN',DawnOfManAudio='',DawnOfManImage='CWC3_Covenant_Dawn.dds',MapImage='CWC3_Covenant_Map.dds'))
    civ += clone('Leaders','LEADER_WASHINGTON',LEADER,dict(
        Description=PREFIX+'LEADER',Civilopedia=PREFIX+'LEADER_PEDIA',CivilopediaTag=PREFIX+'SERAPHINE',
        PackageID=None,ArtDefineTag='CWC3_Covenant_LeaderScene.xml',IconAtlas='CWC3_COVENANT_LEADER_ATLAS',PortraitIndex=0,
        Boldness=2,WarmongerHate=9,Meanness=1,Loyalty=9,Forgiveness=7,DoFWillingness=7,WonderCompetitiveness=6))
    for table in ['Civilization_FreeBuildingClasses','Civilization_FreeTechs','Civilization_FreeUnits']:
        civ += f"CREATE TEMP TABLE CWC3_CovenantStart AS SELECT * FROM {table} WHERE CivilizationType='CIVILIZATION_AMERICA';\nUPDATE CWC3_CovenantStart SET CivilizationType='{CIV}';\nINSERT INTO {table} SELECT * FROM CWC3_CovenantStart;\nDROP TABLE CWC3_CovenantStart;\n"
    civ += f"""INSERT INTO Civilization_Leaders VALUES ('{CIV}','{LEADER}');
INSERT INTO Leader_Traits VALUES ('{LEADER}','{TRAIT}');
INSERT INTO Civilization_UnitClassOverrides(CivilizationType,UnitClassType,UnitType) VALUES ('{CIV}','UNITCLASS_PIKEMAN','{UNIT}');
INSERT INTO Civilization_BuildingClassOverrides(CivilizationType,BuildingClassType,BuildingType) VALUES ('{CIV}','BUILDINGCLASS_TEMPLE','{HALL}');
INSERT INTO Leader_Flavors(LeaderType,FlavorType,Flavor)
 SELECT '{LEADER}',Type,CASE Type WHEN 'FLAVOR_SCIENCE' THEN 8 WHEN 'FLAVOR_CULTURE' THEN 9
 WHEN 'FLAVOR_DEFENSE' THEN 9 WHEN 'FLAVOR_CITY_DEFENSE' THEN 9 WHEN 'FLAVOR_OFFENSE' THEN 2 ELSE 5 END FROM Flavors;
INSERT INTO Leader_MajorCivApproachBiases(LeaderType,MajorCivApproachType,Bias)
 SELECT '{LEADER}',Type,CASE Type WHEN 'MAJOR_CIV_APPROACH_WAR' THEN 1 WHEN 'MAJOR_CIV_APPROACH_HOSTILE' THEN 2
 WHEN 'MAJOR_CIV_APPROACH_FRIENDLY' THEN 7 ELSE 5 END FROM MajorCivApproachTypes;
INSERT INTO Leader_MinorCivApproachBiases(LeaderType,MinorCivApproachType,Bias)
 SELECT '{LEADER}',Type,CASE Type WHEN 'MINOR_CIV_APPROACH_CONQUEST' THEN 1 ELSE 5 END FROM MinorCivApproachTypes;
"""
    cities = ['Last Light','Ember Archive','Quiet Vigil','Silver Lantern','Hallowed Names','Everglow','Stillwater Vault','Memory Spire','Ashen Library','The Patient Flame','Candledeep','Golden Silence','The Unforgotten','Keeper\'s Rest','Twilight Record','Enduring Wick','Lantern Gate','Namesake','Old Radiance','Midnight Athenaeum','The Final Hearth','Serene Watch','Dawn Remnant','Eternal Register']
    spies = ['Wick','Ember','Lantern','Vellum','Ash','Taper','Cinder','Quill','Glimmer','Echo']
    for table,names,key in [('Civilization_CityNames',cities,'CITY'),('Civilization_SpyNames',spies,'SPY')]:
        for i in range(1,len(names)+1): civ += f"INSERT INTO {table} VALUES ('{CIV}','{PREFIX}{key}_{i}');\n"
    write('Civilization',civ)
    unit = clone('Units','UNIT_PIKEMAN',UNIT,dict(Description=PREFIX+'UNIT',Civilopedia=PREFIX+'UNIT_PEDIA',Help=PREFIX+'UNIT_HELP',Strategy=PREFIX+'UNIT_STRATEGY'))
    unit += companions(db,'Unit_','UnitType','UNIT_PIKEMAN',UNIT)
    unit += f"""-- Permanent native Sight/lineage; transient DefenseMod is controlled by native friendly-territory state.
INSERT INTO UnitPromotions(Type,Description,Help,CannotBeChosen,LostWithUpgrade,VisibilityChange,PortraitIndex,IconAtlas,PediaType,PediaEntry)
 VALUES ('{PROMO}','{PREFIX}PROMOTION','{PREFIX}PROMOTION_HELP',1,0,1,9,'ABILITY_ATLAS','PEDIA_ATTRIBUTES','{PREFIX}PROMOTION');
INSERT INTO UnitPromotions(Type,Description,Help,CannotBeChosen,LostWithUpgrade,DefenseMod,PortraitIndex,IconAtlas)
 VALUES ('{DEFENSE}','{PREFIX}DEFENSE','{PREFIX}DEFENSE_HELP',1,1,15,9,'ABILITY_ATLAS');
INSERT INTO Unit_FreePromotions(UnitType,PromotionType) VALUES ('{UNIT}','{PROMO}');
"""
    write('Units',unit)
    building = clone('Buildings','BUILDING_TEMPLE',HALL,dict(Description=PREFIX+'HALL',Civilopedia=PREFIX+'HALL_PEDIA',Help=PREFIX+'HALL_HELP',Strategy=PREFIX+'HALL_STRATEGY'))
    building += companions(db,'Building_','BuildingType','BUILDING_TEMPLE',HALL)
    # Add one to precisely one row, including unusual active baselines with duplicate yield records.
    building += f"""UPDATE Building_YieldChanges SET Yield=Yield+1 WHERE rowid=(SELECT MIN(rowid) FROM Building_YieldChanges WHERE BuildingType='{HALL}' AND YieldType='YIELD_CULTURE');
INSERT INTO Building_YieldChanges(BuildingType,YieldType,Yield) SELECT '{HALL}','YIELD_CULTURE',1
 WHERE NOT EXISTS (SELECT 1 FROM Building_YieldChanges WHERE BuildingType='{HALL}' AND YieldType='YIELD_CULTURE');
"""
    for suffix,kind in DUMMIES:
        typ,cls = 'BUILDING_CWC3_COVENANT_'+suffix,'BUILDINGCLASS_CWC3_COVENANT_'+suffix
        building += f"""INSERT INTO BuildingClasses(Type,DefaultBuilding,Description) VALUES ('{cls}','{typ}','{PREFIX}DUMMY');
INSERT INTO Buildings(Type,BuildingClass,Description,Help,Cost,FaithCost,GoldMaintenance,GreatWorkCount,NeverCapture,NukeImmune,IsDummy,ShowInPedia,ConquestProb,IconAtlas,PortraitIndex)
 VALUES ('{typ}','{cls}','{PREFIX}DUMMY','{PREFIX}DUMMY_HELP',-1,-1,0,-1,1,1,1,0,0,'CIV_COLOR_ATLAS',0);
INSERT INTO Building_YieldChanges(BuildingType,YieldType,Yield) VALUES ('{typ}','YIELD_{kind}',1);
"""
    write('Buildings',building)
    text = dict(CIV="The Candlekeeper's Covenant",SHORT="Candlekeeper's Covenant",ADJECTIVE='Covenant',LEADER='High Keeper Seraphine',
        TRAIT='The Names We Carry',TRAIT_HELP='Permanently destroyed foreign major cities grant one Lost Flame each, up to 12. Each Flame provides +1 [ICON_CULTURE] Culture in the current Capital; every three provide +1 [ICON_RESEARCH] Science. Captures grant nothing. Cities founded by any Covenant are excluded.',
        CIV_PEDIA='No Flame Shall Be Forgotten. The Candlekeepers preserve the names of lost settlements in an underground archive. Each memory becomes a flame, sustaining a patient civilization devoted to Culture, Science and defensive warfare.',
        STRATEGY='Protect the Capital and build Halls of Remembrance. Destruction anywhere in the world accumulates permanent Lost Flames without requiring contact or visibility. Capturing cities grants no Flames. Culture / Science focus; complexity 4/5.',
        LEADER_PEDIA='High Keeper Seraphine is an elderly woman with white hair and calm, bright eyes. Her dark ceremonial robes bear silver embroidery. She carries a lantern containing an ancient flame through an underground archive illuminated by thousands of candles. Patient, reserved and reflective, she protects historical knowledge.',
        UNIT='Vigil Keeper',UNIT_HELP='Replaces the active Pikeman. Eternal Vigil: +1 Sight, and +15% Combat Strength only when defending in friendly territory. Both benefits persist through normal upgrades.',
        UNIT_PEDIA='Vigil Keepers defend the archives and carry the light into the uncertain world beyond.',UNIT_STRATEGY='Retains active CP Pikeman stats, costs, resource requirements, maintenance and upgrade path. Friendly territory uses the native engine rule, including qualifying Open Borders. No offensive bonus.',
        PROMOTION='Eternal Vigil',PROMOTION_HELP='+1 Sight permanently. +15% defense in native friendly territory; no attack bonus. Persists through upgrades.',
        DEFENSE='Eternal Vigil: Friendly Defense',DEFENSE_HELP='+15% defense only. Active while the Eternal Vigil veteran stands in native friendly territory.',
        HALL='Hall of Remembrance',HALL_HELP='Replaces the active Temple, preserving all its normal effects. +1 permanent [ICON_CULTURE] Culture. Covenant-owned Halls add +1 [ICON_RESEARCH] Science at 3 Lost Flames and +2 at 9.',
        HALL_PEDIA='Every lost city becomes a memory. Every forgotten name becomes a flame. The Halls preserve both for generations yet to come.',HALL_STRATEGY='Build in every city. Each Hall adds +1 Culture and conditional Science at 3 and 9 global Lost Flames, including in the Capital.',
        DUMMY='Covenant Memory',DUMMY_HELP='Internal recurring yield controller. Cannot be constructed or purchased.',
        GREETING_1='Welcome, traveler. Tell me your name. I would like to remember it.',
        WAR_1='We sought to preserve your history. You have forced us to become part of it.',
        ATTACKED_1='Another war... another thousand names. Must the world always learn through suffering?',DEFEAT_1='Do not mourn us. Remember us.',
        PEACE_1='Let us preserve what remains, together.',FRIENDLY_1='Your name is welcome in these halls.',NEUTRAL_1='The archive is listening.',HOSTILE_1='What memory will you leave behind?',TRADE_1='Let this agreement be remembered.',FALLBACK_1='We shall remember your words.')
    text['DAWN'] = '[NEWLINE][NEWLINE]'.join([
        'Eternal High Keeper Seraphine, Guardian of the Last Light, your people await your guidance.',
        'Since the beginning of civilization, countless kingdoms have risen beneath the sun.',
        'Their rulers constructed monuments. Their armies marched across continents. Their scholars recorded the achievements of their people.',
        'Yet time has claimed them all.',
        'Cities have fallen. Empires have vanished. Entire peoples have disappeared from the pages of history.',
        'But your ancestors refused to forget.',
        'Within the sacred halls of the Covenant, every lost city became a memory. Every forgotten name became a flame.',
        'Now, the world stands once more upon the threshold of a new age.',
        'Build your cities. Protect your archives. Preserve the knowledge of those who came before.',
        'Will your civilization become the final guardian of history?',
        'Or will its own flame eventually fade into darkness?'])
    for key,names in [('CITY',cities),('SPY',spies)]:
        for i,name in enumerate(names,1): text[f'{key}_{i}']=name
    text.update(CIV5_HEADING_1='No Flame Shall Be Forgotten',CIV5_TEXT_1=text['CIV_PEDIA'],CIV5_HEADING_2=text['TRAIT'],CIV5_TEXT_2=text['TRAIT_HELP'],CIV5_FACTOID_HEADING='The Last Light',CIV5_FACTOID_TEXT='Every forgotten name becomes a flame.',SERAPHINE_NAME=text['LEADER'],SERAPHINE_SUBTITLE='Guardian of the Last Light',SERAPHINE_LIVED='Fictional High Keeper',SERAPHINE_TITLES_1='High Keeper of the Covenant',SERAPHINE_HEADING_1='The Patient Guardian',SERAPHINE_TEXT_1=text['LEADER_PEDIA'],SERAPHINE_FACT_1='Her lantern contains an ancient flame.')
    loc='INSERT INTO Language_en_US(Tag,Text) VALUES\n'+',\n'.join(' ('+literal(PREFIX+k)+','+literal(v)+')' for k,v in text.items())+';\n'
    responses={'RESPONSE_FIRST_GREETING':'GREETING','RESPONSE_DECLAREWAR':'WAR','RESPONSE_ATTACKED':'ATTACKED','RESPONSE_DEFEATED':'DEFEAT','RESPONSE_PEACE_MADE_BY_HUMAN_GRACIOUS':'PEACE','RESPONSE_GREETING_POLITE_HELLO':'FRIENDLY','RESPONSE_GREETING_NEUTRAL_HELLO':'NEUTRAL','RESPONSE_GREETING_HOSTILE_HELLO':'HOSTILE','RESPONSE_TRADE_ACCEPT_GENEROUS':'TRADE','RESPONSE_TRADE_ACCEPT_ACCEPTABLE':'TRADE'}
    for response,tag in responses.items(): loc+=f"INSERT INTO Diplomacy_Responses(LeaderType,ResponseType,Response,Bias) VALUES ('{LEADER}','{response}','{PREFIX}{tag}_%',1);\n"
    loc+=f"INSERT INTO Diplomacy_Responses(LeaderType,ResponseType,Response,Bias) SELECT DISTINCT '{LEADER}',N.ResponseType,'{PREFIX}FALLBACK_%',1 FROM Diplomacy_Responses N WHERE N.LeaderType='LEADER_WASHINGTON' AND NOT EXISTS (SELECT 1 FROM Diplomacy_Responses C WHERE C.LeaderType='{LEADER}' AND C.ResponseType=N.ResponseType);\n"
    write('Text',loc)
    db.close()
    print('Generated Covenant: active Pikeman/Temple clones, 18 controllers and full localization')

if __name__ == '__main__': main()
